        language.add("attribute.name.repeater.torrent_count", "Torrent Count", "连发射击个数");
        language.add("enchantment.confluence.arcane_protection", "Arcane Protection", "奥术防护");
        language.add("enchantment.confluence.arcane_protection.desc", "The mana drawn when taking damage is the value of the maximum mana value multiplied by a certain ratio, and the damage canceled is the value of the product of the damage taken by that ratio", "受到伤害时抽取的魔力为最大魔力值乘积一定比率的值，抵消的伤害为受到的伤害乘积该比率的值");
        language.add("enchantment.confluence.celestial_absorption", "Celestial Absorption", "天穹纳元");
        language.add("enchantment.confluence.celestial_absorption.desc", "Magic weapons that deal magic damage have a chance to drop stars", "使用魔法类武器造成魔法伤害时有概率掉落星星");
        language.add("enchantment.confluence.efficient_magic", "Efficient Magic", "高效魔能");
        language.add("enchantment.confluence.efficient_magic.desc", "The less mana, the less mana is consumed", "魔力值越少，魔力消耗越少");
        language.add("enchantment.confluence.flail_turbine", "Turbine", "涡轮");
        language.add("enchantment.confluence.flail_turbine.desc", "The longer it spins, the higher the damage and spin speed", "越转越强");
        language.add("enchantment.confluence.flail_wind_burst", "Wind Burst", "风暴锤");
        language.add("enchantment.confluence.flail_wind_burst.desc", "Hitting an enemy unleashes a wind burst that knocks back nearby enemies", "击中敌人时生成风暴击飞敌人");
        language.add("enchantment.confluence.mana_mending", "Mana Mending", "魔力修补");
        language.add("enchantment.confluence.mana_mending.desc", "When the mana used once exceeds the threshold, the item's durability is restored, and the amount recovered is rounded down to the amount above the threshold", "一次使用的魔力超过阈值时恢复物品耐久，恢复的量为超过阈值的量向下取整");
        language.add("enchantment.confluence.mana_regeneration", "Mana Regeneration", "魔力再生");
        language.add("enchantment.confluence.mana_regeneration.desc", "Increases the amount of mana that naturally regenerates", "提升魔力自然再生时的量");
        language.add("enchantment.confluence.multi_boomerang", "Multi Shoot Boomerang", "影分身");
        language.add("enchantment.confluence.multi_boomerang.desc", "Fires an additional boomerang", "额外发射一个回旋镖");
        language.add("enchantment.confluence.mystic_surge", "Mystic Surge", "秘能激涌");
        language.add("enchantment.confluence.mystic_surge.desc", "The higher the remaining mana ratio, the higher the attack", "剩余魔力比值越高攻击力越高");
        language.add("enchantment.confluence.soothed_mana", "Soothed Mana", "魔症缓释");
        language.add("enchantment.confluence.soothed_mana.desc", "Reduces the duration of Mana Sickness", "减小魔力病持续时间");
        language.add("enchantment.confluence.spell_desperation", "Spell Desperation", "逆魔狂暴");
        language.add("enchantment.confluence.spell_desperation.desc", "The lower the remaining mana ratio, the higher the attack", "剩余魔力比值越低攻击力越高");
        language.add("enchantment.confluence.summoner_pact", "Summoner's Pact", "召唤师契约");
        language.add("enchantment.confluence.summoner_pact.desc", "Increases minion capacity", "提高仆从容量");
        language.add("enchantment.confluence.whip_sweep", "Whip Sweep", "横扫之鞭");
        language.add("enchantment.confluence.whip_sweep.desc", "Chance to deal a wide area of damage", "概率造成大范围伤害");
        language.add("lore.confluence.meteor_diary", "It's a very thin book, but it seems to have a faint glow.", "很薄的书，但似乎有些荧荧微光。");
        language.add("lore.confluence.mysterious_note.handwriting_0", "✒Rushed handwriting", "✒潦草的笔迹");
        language.add("lore.confluence.mysterious_note.handwriting_1", "✒Neat handwriting", "✒工整的笔迹");
        language.add("lore.confluence.mysterious_note.handwriting_2", "✒Graceful handwriting", "✒清晰的笔迹");
        language.add("lore.confluence.mysterious_note.handwriting_3", "✒Mysterious handwriting", "✒捉摸不透的笔迹");
        language.add("lore.confluence.mysterious_note_0", "Oops, you've found it. Don't tell others that the puppy is hiding here UQYQU", "呜被你发现了，不要告诉别人小狗藏在这里UQYQU");
        language.add("lore.confluence.mysterious_note_1", "Hey, since you've found it, I'll tell you. In fact, one of the animals sleeping with you is probably an informant for the prison pillow.", "嘿，既然被你找到了，就告诉你吧。其实，和你在一块睡觉的某只动物，很可能是牢枕的眼线哦");
        language.add("lore.confluence.mysterious_note_2", "The original brave didn't ask for anything in return. They only hoped that all souls yearning for adventure could freely pick up these precious gifts and shine their own light in the adventure. Please guard this kindness from the brave and don't let the shadow of interests obscure the light of freedom and hope in the afterlife.", "最初的勇者不求回报，只愿所有向往冒险的灵魂，都能自由地拾取这些珍贵馈赠，在冒险中绽放属于自己的光芒。请守护这份来自勇者的善意，莫让利益的阴霾，遮蔽了来世自由与希望的光芒。");
        language.add("lore.confluence.mysterious_note_3", "I hope that the adventurer who sees this note can have a smooth study, a successful job, and everything goes well in life. No matter what the haze is, it will pass quickly because we all have to move forward towards tomorrow.", "希望看到这张字条的冒险者可以学习顺心，工作顺利，生活事事如意，不管什么阴霾都会很快过去的因为我们都要向着明天前进。");
        language.add("lore.confluence.mysterious_note_4", "When will Confluence Fun Stuff start production? I've been waiting until I'm stupid.", "汇流乐事什么时候才开始制作啊，我都已经等的变成傻子了");
        language.add("lore.confluence.mysterious_note_5", "Late-night snacks should be breakfast. Opponents may live healthier, but much duller, lives.", "夜宵就应该当早餐吃，反对的人会度过相对健康但非常无趣的一生");
        language.add("lore.confluence.mysterious_note_structure_0_0", "I have secretly investigated this dungeon... Instead of being considered a dungeon, it is rather seen as a long lost city. Besides the creaking skeletons, there are several buildings like apartments and a wide variety of public structures. These skeletons are said to be the locals here but nobody knows how they could've fallen into this situation...", "我暗中调查了整个地牢…与其说是地牢，它却更像一座深埋在地下的城市。除了咯咯作响的骷髅们，这里有不少看起来像是居民楼以及各类公共设施的建筑；有迹象表明，那些骷髅曾是这里的原住民，真不知道它们究竟经历了什么才堕落到如此地步…");
        language.add("lore.confluence.mysterious_note_structure_0_1", "However, indeed, the wonder is those rare rooms which look like armories with a huge sword on top. Each \"armory\" contains plenty equipment, with a locked chest... which I am unable to open but it lets me know that it contains valuables.", "而真正异乎寻常的是那些少见的，装潢看上去像是军械库一样的建筑，它们的顶部插着巨剑，每一座“军械库”都包含着大量的武器装备，还有一个上了锁的箱子……我暂时还没法打开它，但我知道里面的东西绝对不简单…");
        language.add("lore.confluence.mysterious_note_structure_1_0", "Those terrifying monsters are truly mad! I wish to leave this place... However, I found some keys in these strange structures resembling churches and those disgusting slimy monsters... There must be treasure here, but I haven't found it yet...", "那些可怕的怪物实在是太疯狂了！我想离开这里…但我在类似教堂的奇怪建筑和那些恶心的粘液生物里发现了一些钥匙…这里一定有宝藏，只是我暂时还没有找到…");
        language.add("lore.confluence.mysterious_note_structure_2_0", "Mysterious clues of an evil ritual were etched into the enigmatic murals I found within the ancient ruins… I sketched them down. I had no idea what these so-called \"Crying Obsidian\" were before, but now I’ve finally found them on these towering, ancient doorframes… There must be countless secrets in this world that I still don’t know about. Additionally, near the patterns of the murals, I discovered several inscriptions. \"Confusion, confusion, look towards the direction of the falling entity. The guide that directs you to the extraterrestrial object can still offer you new guidance. Sacrifice, using the weeping stone deity. Behold, its deep, lifeless eye sockets, pointing towards its homeland, long since departed.\"", "我在神秘的遗迹中的不明壁画上看到了一些邪恶仪式的线索…我把他们描绘了下来…我原本不知道这所谓的“哭泣的黑曜石”是什么，如今终于在这些耸立的古老门框上找到了它们…这个世界上一定还有无数的秘密是我所不知道的。另外我还在壁画的图案附近发现了几段话。“迷惘，迷惘，看那天降之物的方向。指引你寻找天外来物的向导，仍能给你新的引导。祭祀，用那潸潸流泪的石神。看啊，深邃的失活的眼窝，指向它早已远离的故乡。”");
        language.add("lore.confluence.mysterious_slate_0", "“A fun fact: In fact, summoners need to communicate with their summoned creatures spiritually. The armor protection can't be too thick, otherwise it will affect the communication.”", "“冷知识：其实召唤师要和召唤物进行心灵沟通，盔甲防护不能太厚否则会影响沟通。”");
        language.add("lore.confluence.mysterious_slate_1", "“It all started when the Moon Lord sold the... (The content is covered by blood, and the whole picture can't be seen clearly)”", "“这一切要从月球领主卖的氵……（内容被血迹覆盖了，看不清全貌）”");
        language.add("lore.confluence.research_on_cloud_blocks_1", "It's obviously a very thick book, but it feels so light in the hand. Judging from the title, it seems there is another volume?", "明明很厚一本书，拿在手上却轻飘飘的。看标题的样子好像还有另一本？");
        language.add("lore.confluence.research_on_cloud_blocks_2", "The pages feel very soft, just like silk. Judging from the title, it seems there is another volume?", "书页摸起来非常柔软，就好像丝绸一样。看标题的样子好像还有另一本？");
        language.add("lore.confluence.research_on_wheat_mutation", "There are some powders mixed in the pages, but it doesn't seem to be the powder from the aging of the pages...", "书页中混杂着一些粉末，但是好像并不是书页老化出来的粉末......");
        language.add("lore.confluence.village_exploration", "It's hard to tell the exact age, but it seems to be very well - packaged...", "看不出详细的年代，但是感觉包装很精良的样子......");
        language.add("tooltip.confluence.ability.chlorophyte_homing", "Special Effect: Homes in on nearby targets and leaves a bright green trail", "特殊效果：会追踪附近的目标，并留下明亮的绿色轨迹");
        language.add("tooltip.confluence.ability.crystal_split", "Special Effect: Splits backward into 2 shards at 50% damage; shards pass through blocks", "特殊效果：命中后向后分裂为 2 枚碎片，伤害为原弹 50%，可穿过方块");
        language.add("tooltip.confluence.ability.cursed_debuff", "Special Effect: Applies Wither", "特殊效果：施加凋零");
        language.add("tooltip.confluence.ability.explosive", "Special Effect: Explodes on impact", "特殊效果：命中后爆炸");
        language.add("tooltip.confluence.ability.high_velocity_damage_decay", "Special Effect: Damage drops by 15% after each hit", "特殊效果：每次命中后伤害降低 15%");
        language.add("tooltip.confluence.ability.ichor_debuff", "Special Effect: Applies Ichor and reduces armor", "特殊效果：施加灵液，降低目标护甲");
        language.add("tooltip.confluence.ability.luminite_damage_decay", "Special Effect: Damage drops by 4% after each hit, down to 0", "特殊效果：每次命中后伤害降低 4%，最低降至 0");
        language.add("tooltip.confluence.ability.meteor_ricochet", "Special Effect: Bounces once or pierces one enemy, but cannot do both", "特殊效果：可反弹 1 次或穿透 1 个敌怪，但不能同时进行");
        language.add("tooltip.confluence.ability.nano_ricochet", "Special Effect: Redirects toward the nearest enemy after hitting a block at 66% damage, once", "特殊效果：击中方块后弹向最近敌怪，造成 66% 伤害，最多弹射 1 次");
        language.add("tooltip.confluence.ability.party_confetti", "Special Effect: Releases confetti when hitting an enemy or block", "特殊效果：命中敌怪或方块时释放彩纸");
