        language.add("tooltip.confluence.void_storage.overflow", "When open, collects inventory overflow and allows quick use of stored potions", "开启时，背包满后自动收纳物品，支持快捷使用库存内的药水");
        language.add("tooltip.confluence.void_storage.shared", "Accesses your personal storage, shared with the Void Vault", "访问你的个人虚空库存，与虚空保险库共用储物空间");
        language.add("tooltip.confluence.void_storage.toggle", "Right-click with an empty cursor in the inventory to toggle open or closed", "在物品栏中空手右键切换开启／关闭状态");
        language.add("tooltip.confluence.yoyo.afterimage", "Every %s hits spawn a second-form Eye of Cthulhu afterimage that dashes at nearby enemies", "每 %s 次命中产生克苏鲁之眼二阶段的影子，向附近敌怪冲锋");
        language.add("tooltip.confluence.yoyo.bees", "1/3 chance to release a bee on hit; benefits from the Hive Pack", "命中有 1/3 概率释放蜜蜂，可受蜂巢背包强化");
        language.add("tooltip.confluence.yoyo.cascade", "1/3 chance to ignite; every %s hits fire a fiery explosion, except while offstring", "命中有 1/3 概率点燃，每 %s 次命中发射爆裂弹；脱手时不产生爆裂弹");
        language.add("tooltip.confluence.yoyo.critical", "+20% critical strike chance; critical strikes deal 2.5x damage", "额外 20% 暴击率，暴击造成 2.5 倍伤害");
        language.add("tooltip.confluence.yoyo.crystals", "Every %s hits create a crystal explosion, scattering %s shards", "每 %s 次命中产生水晶爆炸，向四周散射 %s 枚碎块");
        language.add("tooltip.confluence.yoyo.exist_time", "Using Time", "使用时间");
        language.add("tooltip.confluence.yoyo.frostbite", "2/3 chance to inflict Frostbite for 2–5 seconds on hit", "命中有 2/3 概率施加 2–5 秒冻伤");
        language.add("tooltip.confluence.yoyo.hellfire", "Inflicts Hellfire for 3–8 seconds on hit", "命中施加 3–8 秒狱炎");
        language.add("tooltip.confluence.yoyo.hit_effect", "Hit Effect", "命中效果");
        language.add("tooltip.confluence.yoyo.max_range", "Max Range", "最大射程");
        language.add("tooltip.confluence.yoyo.terrarian", "Continuously fires energy projectiles toward nearby enemies", "持续向附近敌人发射能量弹");
        language.add("tooltip.confluence.yoyo.venom", "Inflicts Acid Venom for 2 seconds on hit", "命中施加 2 秒酸性毒液");
        language.add("tooltip.confluence.yoyo.waves", "A whirlpool expands attack range; every %s hits fire %s piercing waves", "漩涡扩大攻击范围，每 %s 次命中发射 %s 道穿透波浪");
        language.addTooltip(ModEffects.ACID_VENOM.get(), "Losing life; Cannot regenerate life", "缓慢损失生命值，无法再生生命");
