        language.addTooltip(ModEffects.DANGER_SENSE.get(), "You can see nearby hazards; press [%s] for detailed information", "你可以看到附近的危险；按下[%s]显示具体信息");
        language.addTooltip(ModEffects.DELICIOUS.get(), "Doubles positive effects, halves negative effects", "正面效果翻倍，负面效果减半");
