        language.addTooltip(ConsumableItems.WORM_FOOD.get(), "Right - click to summon the Eater of Worlds. It shuttles through the huge rift filled with corruptive poisonous fog.", "右键使用以召唤世界吞噬者，它会在充满腐化毒雾的巨大裂谷中穿梭");
        language.add("tooltip.item.confluence.worm_food.1", "It smells like a rotten rib and seems to have a strong attraction to those mutated Terraria creatures.", "闻起来像一块烂掉了的排骨，似乎对那些病变了的泰拉生物有极强的吸引力。");
        language.add("tooltip.item.confluence.worm_food.2", "“It wants to devour more... more and more and more and more…”", "“它还要吞噬更多…更多更多更多更多…”");
        language.addTooltip(PotionItems.WORMHOLE_POTION.get(), "Teleports the player to a teammate when they click their icon on the map.", "当玩家在地图上点击队友图标时将玩家传送至队友的位置处。");
        language.addTooltip(PotionItems.WRATH_POTION.get(), "10% increased damage", "伤害提高10%");
        language.addTooltip(AccessoryItems.XENON_MOSS_FISHING_BOBBER.get(), "Increases fishing power, fishing bobber glows", "增加渔力，钓鱼浮标会发光");
        language.addTooltip(AccessoryItems.YELLOW_COUNTERWEIGHT.get(), "Throws a counterweight on yoyo hits; counterweights do not stack", "悠悠球命中后掷出平衡锤；不与其他平衡锤重复叠加");
        language.addTooltip(AccessoryItems.YELLOW_YOYO_STRING.get(), "Increases yoyo range by 25% + 2 blocks and spin duration by 50%", "增加悠悠球射程 25% + 2 格，滞空时间增加 50%");
        language.addTooltip(AccessoryItems.YOYO_BAG.get(), "Combines yoyo string, glove and counterweight effects", "结合绳、手套和平衡锤的效果");
        language.addTooltip(AccessoryItems.YOYO_GLOVE.get(), "Spawns a second yoyo on hit; the duplicate consumes spin duration faster", "命中后生成副悠悠球；副球使有限滞空时间消耗加快");
        language.addTooltip(SwordItems.ZENITH.get(), "When ten scattered pieces are found again and ten powers converge, this blazing weapon will descend from the zenith of the sky, bestowed upon the hero who liberated Confluence: Otherworld.", "当十块散碎的拼图被重新找回，十股力量汇流之际，这把炽热的神兵将从天穹之顶降下，赐予解放汇合交流来世之英雄");
        language.add("tooltip.item.confluence.zenith.1", "“Why not try throwing it into Shimmer?”", "“为什么不丢进微光里试试呢？”");
        language.add("tooltip.item.terra_curio.arcane_flower.1", "Automatically uses mana potions when needed", "需要时自动使用魔力药水");
        language.add("tooltip.item.terra_curio.arcane_flower.2", "Enemies are less likely to target you", "敌人不太可能以你为目标");
        language.add("tooltip.item.terra_curio.boredoms_pact_falling_resolve.1", "           ", "           ");
        language.add("tooltip.item.terra_curio.boredoms_pact_falling_resolve.2", "The blood of the indolent has soaked into the stardust core, condensing into this breathing cursed stone.", "怠惰者的血浸透了星核，凝成这颗会呼吸的诅咒石。");
        language.add("tooltip.item.terra_curio.boredoms_pact_falling_resolve.3", "When in motion, the veins of the earth surge, and blades cleave through the long night; when still, the earth's heart beats, and the sky opens its single eye.", "动，则岩脉奔涌，刃锋割裂长夜；静，则地心跳搏，苍穹睁开独眼。");
        language.add("tooltip.item.terra_curio.boredoms_pact_falling_resolve.4", "The ancient god inscribed punishment into the contract: eight heartbeats of stillness summon the judgment of a falling star.", "古神将惩罚编入契约：八次心跳的静止，便召来陨星审判。");
        language.add("tooltip.item.terra_curio.boredoms_pact_falling_resolve.5", "It doesn't remain silent like a golem - it cackles when boulders shatter shinbones:", "它不像魔像般沉默——巨石砸碎胫骨时会尖笑：");
        language.add("tooltip.item.terra_curio.boredoms_pact_falling_resolve.6", "'Look, even the stones understand the way of survival better than your legs.'", "'看啊，连石头都比你的双腿更懂生存之道。'");
        language.add("tooltip.item.terra_curio.boredoms_pact_falling_resolve.7", "The wearer will eventually understand that so - called 'invincibility' merely means outrunning death by a single second.", "佩戴者终将明白：所谓'不摧'，不过是逃得比死亡快一秒。");
        language.add("tooltip.item.terra_curio.boredoms_pact_falling_resolve.8", "And the soul has long been crushed into dust in the rock crevices, more desolate than the empty shell of a golem.", "而灵魂早被碾成岩缝里的尘，比魔像的空壳更荒芜。");
        language.add("tooltip.item.terra_curio.celestial_cuffs.1", "Restores mana when damaged", "受到伤害时会恢复魔力");
        language.add("tooltip.item.terra_curio.celestial_cuffs.2", "Increases maximum mana by 20", "最大魔力增加20");
        language.add("tooltip.item.terra_curio.guide_voodoo_doll.1", "Hold and press to switch type", "手持并长按使用以切换形态");
        language.add("tooltip.item.terra_curio.lavaproof_tackle_bag.1", "Allows fishing in lava", "可在熔岩中钓鱼");
        language.add("tooltip.item.terra_curio.magic_cuffs.1", "Restores mana when damaged", "受伤时恢复魔力");
        language.add("tooltip.item.terra_curio.magnet_flower.1", "Automatically uses mana potions when needed", "需要时自动使用魔力药水");
        language.add("tooltip.item.terra_curio.magnet_flower.2", "Increases pickup range for mana stars", "扩大魔力星的拾取范围");
        language.add("tooltip.item.terra_curio.mana_cloak.1", "Reduces mana usage by 8%", "魔力消耗降低8%");
        language.add("tooltip.item.terra_curio.mana_cloak.2", "Automatically uses mana potions when needed", "需要时自动使用魔力药水");
        language.add("tooltip.item.terra_curio.mana_cloak.3", "Stars will fall when you take damage", "受到伤害后会使星星坠落");
        language.add("tooltip.item.terra_curio.mana_flower.1", "Automatically uses mana potions when needed", "需要时自动使用魔力药水");
        language.add("tooltip.item.terra_curio.mana_regeneration_band.1", "Increases mana regeneration speed", "提高魔力再生速度");
        language.add("tooltip.item.terra_curio.mechanical_lens.1", "Right-click in the backpack to toggle on/off.", "背包内右键点击可开关");
        language.add("tooltip.item.terra_curio.radio_thing.1", "'Forbidden Knowledge echoes from the radio...'", "“禁忌的知识在其中回响……”");
        language.add("tooltip.item.terra_curio.spectre_goggles.1", "Right-click in the backpack to toggle on/off.", "背包内右键点击可开关");
        language.add("tooltip.jei.brewing_stand_terra_potion", "The intermediate product is a Chaos Potion, which needs to be used again as a raw material and mixed with the next ingredient.", "中间产物为混沌药水，需要再次将其作为原料，与下个材料混合");
